from pathlib import Path
from PIL import Image
import html, json, re, csv
from data import PRODUCTS, WIRE
ROOT=Path(__file__).resolve().parent.parent; SITE=ROOT/'site'; IMG=SITE/'assets/img'
IMG.mkdir(parents=True,exist_ok=True)
for p in IMG.iterdir(): p.unlink()
def image(path, alt, eager=False):
    source=ROOT/'reference/img/images'/path
    im=Image.open(source).convert('RGB'); name=path.replace('/','-').lower().replace(' ','-').rsplit('.',1)[0]+'.jpg'; im.save(IMG/name,quality=82,optimize=True)
    w,h=im.size
    return f'<img src="/assets/img/{name}" alt="{html.escape(alt)}" width="{w}" height="{h}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def cards():
    out=''
    for slug,(title,desc,photos) in sorted(PRODUCTS.items(), key=lambda item: not bool(item[1][2])):
        pic=f'<div class="card-image">{image(photos[0],title)}</div>' if photos else ''
        out+=f'<a class="product-card{" text-only" if not photos else ""}" href="/products/{slug}/">{pic}<div class="card-title"><h3>{title}</h3></div></a>'
    return out
def band(): return '<section class="quote-band"><div class="wrap band-inner"><h2>Request a quote</h2><a class="button light" href="/contact/#quote">Request a quote </a></div></section>'
def layout(title,desc,body,path):
    nav=[('Products','/products/'),('Design & prototyping','/design-prototyping/'),('About','/about/'),('Careers','/careers/'),('Contact','/contact/')]
    links=''.join(f'<a href="{u}"'+(' aria-current="page"' if path==u or (u=='/products/' and path.startswith(u)) else '')+f'>{t}</a>' for t,u in nav)
    ld={'@context':'https://schema.org','@type':'Organization','name':'Stevens Wire Products, Inc.','url':'https://stevenswire.com/','telephone':'(765) 966-5534','faxNumber':'(765) 962-3586','email':'office@stevenswire.com','address':{'@type':'PostalAddress','streetAddress':'351 NW F Street','addressLocality':'Richmond','addressRegion':'IN','postalCode':'47374-2229','addressCountry':'USA'}}
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>{html.escape(title)} | Stevens Wire Products</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta property="og:title" content="{html.escape(title)} | Stevens Wire Products"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="https://stevenswire.com{path}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/css/site.css"><script type="application/ld+json">{json.dumps(ld)}</script><script src="/assets/js/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Stevens Wire Products home"><span class="brand-symbol">S<span>W</span></span><span>STEVENS <small>WIRE PRODUCTS, INC.</small></span></a><button class="menu" aria-expanded="false" aria-controls="nav">Menu <span aria-hidden="true">☰</span></button><nav id="nav" aria-label="Main navigation">{links}<a class="header-phone" href="tel:+17659665534">(765) 966-5534</a><a class="nav-quote" href="/contact/#quote">Request a quote </a></nav></div></header><main id="main">{body}</main><footer><div class="wrap footer-grid"><div><a class="footer-brand" href="/">STEVENS <span>WIRE PRODUCTS, INC.</span></a><p>351 NW F Street<br>Richmond, IN 47374-2229 USA</p></div><div><p><a href="tel:+17659665534">(765) 966-5534</a><br>Fax: (765) 962-3586<br><a href="mailto:office@stevenswire.com">office@stevenswire.com</a></p></div><div><p><a href="/products/">Products</a><br><a href="/design-prototyping/">Design & prototyping</a><br><a href="/assets/docs/brochuredesign-2011.pdf">Brochure (PDF)</a></p></div></div><div class="wrap footer-bottom">Stevens Wire Products, Inc.</div></footer></body></html>'''
def intro(title,desc): return f'<section class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> / <a href="/products/">Products</a></p><h1>{title}</h1><p>{desc}</p></div></section>'
def write(path,title,desc,body):
    dest=SITE/path.strip('/')/'index.html' if path!='/' else SITE/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(layout(title,desc,body,path))
write('/','Custom welded wire fabrications','Stevens Wire Products is a family owned manufacturing company founded in 1960 by W. Ray Stevens Jr.',f'''<section class="hero"><div class="wrap hero-inner"><div><h1>Custom welded wire fabrications</h1><p>Stevens Wire Products is a family owned manufacturing company founded in 1960 by W. Ray Stevens Jr.</p><div class="actions"><a class="button" href="/contact/#quote">Request a quote </a><a class="text-link" href="/products/">Explore products </a></div></div><div class="hero-aside">{image("building.jpg", "Stevens Wire Products building", True)}</div></div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="index">01 / PRODUCT LINES</span><h2>Product lines</h2></div></div><div class="products-grid">{cards()}</div></div></section><section class="capability"><div class="wrap capability-grid"><div><span class="index">02 / CAPABILITIES</span><h2>Wire fabrication</h2></div><div><p class="large">{WIRE}</p><a class="inline-link" href="/design-prototyping/">Design &amp; prototyping</a></div></div></section>{band()}''')
write('/products/','Product lines',WIRE,f'''<section class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> / Products</p><h1>Product lines</h1><p>{WIRE}</p></div></section><section class="section"><div class="wrap"><div class="products-grid">{cards()}</div></div></section><section class="capability"><div class="wrap two-col"><div><span class="index">PRODUCTION</span><h2>Production capabilities</h2><p>Our variety of resistance welding and forming equipment allows us to manufacture an array of wire products including the simplest of wire forms to the most complex of fabrications.</p><p>At Stevens, we go the extra mile by investing in special fixuring and forming equipment for large quantity production runs. Our state of the art tooling is built to enable the use of the tightest of tolerances, including robotic compatible applications.</p></div><div><span class="index">QUALITY</span><h2>Quality control</h2><p>Each employee takes pride in producing a quality product for our customers by verifying the accuracy of every operation required to build the product, from initial cutting to final inspection. A random sample is also taken to assure no changes and no surprises.</p></div></div></section>{band()}''')
for slug,(title,desc,photos) in PRODUCTS.items():
    gallery=''.join('<div class="gallery-item">'+image(p,title)+'</div>' for p in photos)
    desc = desc if slug in ('material-handling', 'medical') else ''
    product_list = '<nav class="product-list" aria-label="Product lines">'+''.join(f'<a href="/products/{key}/"'+(' aria-current="page"' if key == slug else '')+f'>{item[0]}</a>' for key,item in PRODUCTS.items())+'</nav>'
    write('/products/'+slug+'/',title,desc,intro(title,desc)+f'<section class="section"><div class="wrap">'+(f'<div class="gallery">{gallery}</div>' if gallery else f'<div class="product-detail"><div><p class="large">{WIRE}</p><a class="inline-link" href="/contact/#quote">Request a quote</a></div>{product_list}</div>')+'</div></section>'+band())
write('/design-prototyping/','Design & prototyping','We can provide full CAD design or assist in completing your current design.', '''<section class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> / Design &amp; prototyping</p><h1>Design &amp; prototyping</h1><p>Our engineering department is ready to help you design the wire product that best suits your needs.</p></div></section><section class="section"><div class="wrap two-col"><div><span class="index">01 / DESIGN</span><h2>Product design</h2><p>We can provide full CAD design or assist in completing your current design. We are always willing to offer suggestions to improve function and cost of your current products.</p></div><div><span class="index">02 / PROTOTYPING</span><h2>Working prototypes</h2><p>Our highly trained tool and die staff is ready to transform CAD designs into working prototypes. Products are ready for immediate production upon sample approval.</p></div></div></section>'''+band())
write('/about/','About Stevens Wire Products','Stevens Wire Products is a family owned manufacturing company founded in 1960 by W. Ray Stevens Jr.', '''<section class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> / About</p><h1>About Stevens Wire Products</h1><p>Stevens Wire Products is a family owned manufacturing company founded in 1960 by W. Ray Stevens Jr.</p></div></section><section class="section"><div class="wrap two-col"><div><h2>Our history</h2><p>Ray’s hard working attitude and strong belief in quality, customer service and competitive pricing are still deeply rooted in our mission statement today.</p>'''+image('building.jpg','Stevens Wire Products building')+'''</div><div><h2>Our mission</h2><ul class="values"><li>Be one of the world’s best wire products manufacturers known for outstanding products, quality and customer satisfaction.</li><li>Be a leader in our industry in the search for and use of new technologies.</li><li>Be an adaptive, responsive organization known for integrity, individual respect, empowerment and open communication.</li></ul></div></div></section>'''+band())
write('/careers/','Careers','Application and/or resume accepted at our office.', '''<section class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> / Careers</p><h1>Careers</h1><p>Application and/or resume accepted at our office:</p></div></section><section class="section"><div class="wrap two-col"><div><h2>Apply</h2><p>Monday–Friday<br>8:00am–3:30pm</p><p>351 NW F Street<br>Richmond, IN 47374-2229 USA</p><p><a href="mailto:employment@stevenswire.com">employment@stevenswire.com</a><br><a href="tel:+17659665534">(765) 966-5534</a></p><p>First shift runs from 7:00am - 3:30pm - weekdays</p></div><div><h2>Benefits</h2><ul class="values"><li>Full time employment</li><li>Health, dental and vision benefit package</li><li>IRA benefit</li><li>Paid vacation and holidays</li></ul><p>EOE</p></div></div></section>''')
fields=[('Name','name','text','name',True),('Company','company','text','organization',False),('Email','email','email','email',True),('Phone','phone','tel','tel',False),('Wire type/diameter','wire','text','off',False),('Quantity','quantity','text','off',False),('Drawing or description','drawing','textarea','off',False),('Message','message','textarea','off',True)]
form=''.join(f'<label>{label}'+(f'<textarea name="{name}" autocomplete="{auto}"'+(' required' if req else '')+'></textarea>' if typ=='textarea' else f'<input type="{typ}" name="{name}" autocomplete="{auto}"'+(' required' if req else '')+'>')+'</label>' for label,name,typ,auto,req in fields)
write('/contact/','Contact','Please Email Request for Quotes & Engineering Files to Frank Lahmann.',f'''<section class="page-head"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> / Contact</p><h1>Contact us</h1><p>Stevens Wire Products, Inc.</p></div></section><section class="section"><div class="wrap contact-grid"><div><h2>Our office</h2><p>351 NW F Street<br>Richmond, IN 47374-2229 USA</p><p><a href="tel:+17659665534">(765) 966-5534</a><br>Fax: (765) 962-3586<br><a href="mailto:office@stevenswire.com">office@stevenswire.com</a></p><h2>Contact our office</h2><p>Frank Lahmann, President<br><a href="mailto:frank@stevenswire.com">frank@stevenswire.com</a></p><p>Tracey Frame, Office Manager<br><a href="mailto:tracey@stevenswire.com">tracey@stevenswire.com</a></p><p>Chris Lahmann<br><a href="mailto:chris@stevenswire.com">chris@stevenswire.com</a></p><p>Please Email Request for Quotes &amp; Engineering Files to Frank Lahmann: <a href="mailto:frank@stevenswire.com">frank@stevenswire.com</a>.</p></div><div id="quote" class="form-panel"><h2>Request a quote</h2><!-- Replace the mailto handler with a production form endpoint here. --><form id="quote-form">{form}<button class="button" type="submit">Prepare email </button><p id="form-status" role="status"></p></form></div></div></section>''')
# Redirect all crawled paths and the original brochure.
mapping={'history.html':'/about/','design.html':'/design-prototyping/','prodlines.html':'/products/','contact.html':'/contact/','index.htm':'/','jobs.html':'/careers/','material.html':'/products/material-handling/','food.html':'/products/food-service/','medical.htm':'/products/medical/','display.html':'/products/displays/','shelving.html':'/products/shelving-guards/','copyright.html':'/','guards.html':'/products/shelving-guards/','wire-forms.html':'/products/wire-forms/','conveyor.html':'/products/conveyor/','frybig.html':'/products/food-service/','foodtray.html':'/products/food-service/','displaylong.html':'/products/displays/','materialbig3.html':'/products/material-handling/','materialbig1.html':'/products/material-handling/','materialbig2.html':'/products/material-handling/','display4big.html':'/products/displays/','display1big.html':'/products/displays/','brochuredesign-2011.pdf':'/assets/docs/brochuredesign-2011.pdf'}
(SITE/'_redirects').write_text(''.join('/'+k+' '+v+' 301\n' for k,v in mapping.items()))
(SITE/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  X-Robots-Tag: noindex\n/assets/*\n  Cache-Control: public, max-age=31536000, immutable\n')
(SITE/'robots.txt').write_text('User-agent: *\nDisallow: /\nSitemap: https://stevenswire.com/sitemap.xml\n')
paths=['/','/about/','/design-prototyping/','/products/']+['/products/'+x+'/' for x in PRODUCTS]+['/careers/','/contact/']
(SITE/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://stevenswire.com'+p+'</loc></url>' for p in paths)+'</urlset>')
(SITE/'404.html').write_text(layout('Page not found','Page not found.','<section class="page-head"><div class="wrap"><h1>Page not found</h1><p>We cannot locate the page you&#39;re looking for.</p><a class="button" href="/">Return home</a></div></section>','/404.html'))
